sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var Constants = x_gegis_ins_policy.Constants;
    var APPLIED = Constants.CHOICE.DISPOSITION.APPLIED;

    var isNewlyApplied = current.operation() == 'insert' && String(current.getValue('disposition')) == APPLIED;
    var justConfirmed = current.operation() == 'update' && previous &&
        String(previous.getValue('disposition')) != APPLIED && String(current.getValue('disposition')) == APPLIED;
    if (!isNewlyApplied && !justConfirmed)
        return;

    // GUIDELINE allow-list: fields ExtractionApplier can write onto submission_line
    // / location that represent exclusion/construction/policy-period/LOB-relevant
    // content. ASSUMPTION (documented once, here and mirrored in the sibling BRs):
    // total_insured_value is the only one with its OWN trigger_reason code
    // (tiv_change); line_of_business and construction_type are bucketed under
    // property_count_change by UWTriggerReasonResolver until the catalog grows
    // dedicated codes for them - see that script include's header comment.
    var GUIDELINE_ALLOW_LIST = ['total_insured_value', 'line_of_business', 'construction_type'];

    var submissionId = String(current.getValue('submission'));
    if (!submissionId) {
        gs.error('[UW Guideline trigger on extraction confirmed] extraction ' + current.getUniqueValue() +
            ' has no submission - cannot resolve its submission_line(s), skipped');
        return;
    }

    var submissionGr = new GlideRecord('x_gegis_ins_policy_submission');
    var submissionType = submissionGr.get(submissionId) ? String(submissionGr.getValue('submission_type')) : '';

    var newSnapshot = _buildSnapshot(current.getUniqueValue(), GUIDELINE_ALLOW_LIST);
    var priorExtractionId = String(current.getValue('supersedes'));
    var oldSnapshot = priorExtractionId ? _buildSnapshot(priorExtractionId, GUIDELINE_ALLOW_LIST) : {};

    var changedFields = new UWFieldSnapshotDiff().diff(oldSnapshot, newSnapshot, GUIDELINE_ALLOW_LIST);

    var triggerReasonId = new UWTriggerReasonResolver().resolve({
        consumer: 'uw_guideline',
        changedFields: changedFields,
        isFirstEver: !priorExtractionId,
        isRenewal: submissionType == Constants.CHOICE.SUBMISSION_TYPE.RENEWAL,
        isEndorsement: submissionType == Constants.CHOICE.SUBMISSION_TYPE.ENDORSEMENT
    });
    if (!triggerReasonId)
        return; // resolver already gs.error'd with full context - do not insert a header row with a broken trigger_reason

    var versionService = new UWGuidelineVersionService();
    var lines = new GlideRecord('x_gegis_ins_policy_submission_line');
    lines.addQuery('submission', submissionId);
    lines.query();
    var created = 0;
    while (lines.next()) {
        if (versionService.createNextVersion(lines.getUniqueValue(), current.getUniqueValue(), triggerReasonId))
            created++;
    }
    if (!created)
        gs.error('[UW Guideline trigger on extraction confirmed] no submission_line rows found for submission ' +
            submissionId + ' - no uw_guideline_version created for extraction ' + current.getUniqueValue());

    function _buildSnapshot(extractionId, allowList) {
        var snapshot = {};
        var field = new GlideRecord('x_gegis_ins_policy_extraction_field');
        field.addQuery('extraction', extractionId);
        field.addQuery('target_column', 'IN', allowList.join(','));
        field.query();
        while (field.next())
            snapshot[String(field.getValue('target_column'))] = String(field.getValue('final_value'));
        return snapshot;
    }

})(current, previous);
